import os,json,time,datetime
from pathlib import Path
prefix='/groups/banfield/projects/environmental/sr/srvp2020/Jacob/lanthanide_binding/on_density_scanner/alchemical_bvs/workspaces/lanm_coupled_mechanics_20261017/lbt_omol_memory_recovery_v1/run/'
def snap():
 rows=[];groups={}
 for p in Path('/proc').iterdir():
  if not p.name.isdigit():continue
  try:
   if p.stat().st_uid!=601:continue
   cwd=os.readlink(p/'cwd')
   if not cwd.startswith(prefix):continue
   cmd=(p/'cmdline').read_bytes().replace(b'\0',b' ').decode(errors='replace')
   if 'orca' not in cmd:continue
   st=(p/'stat').read_text().rsplit(')',1)[1].split();status={}
   for line in (p/'status').read_text().splitlines():
    if line.startswith(('VmRSS:','VmSwap:','Threads:')):
     a,b=line.split(':',1);status[a]=b.strip()
   group=(p/'cgroup').read_text().strip()
   rows.append({'pid':int(p.name),'command':cmd,'cwd':cwd,'state':st[0],'user_ticks':int(st[11]),'system_ticks':int(st[12]),'start_ticks':int(st[19]),'memory':status,'cgroup':group})
   for line in group.splitlines():
    a,b,c=line.split(':',2)
    if not b:
     base=Path('/sys/fs/cgroup')/c.lstrip('/')
     for ancestor in [base]+list(base.parents):
      if 'job_16680' not in str(ancestor):continue
      for name in ('memory.current','memory.max','memory.events','cpu.stat'):
       f=ancestor/name
       if f.exists():groups[str(f)]=f.read_text()
  except (FileNotFoundError,PermissionError,ProcessLookupError):continue
 return {'utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'monotonic_seconds':time.monotonic(),'clock_ticks_per_second':os.sysconf('SC_CLK_TCK'),'rows':rows,'cgroup_metadata':groups}
a=snap();time.sleep(10);b=snap();print(json.dumps({'first':a,'second':b},indent=2))
